"""Write clearly labelled *synthetic* SeedGuard CSV schema demos (not real ECR results)."""

import os
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)

import collect_results

OUT_DIR = os.path.join(ROOT, "src_emo", "save")
OUT = os.path.join(OUT_DIR, "seedguard_schema_demo")

NOTE = (
    "SYNTHETIC SCHEMA DEMO — not measured ECR metrics. "
    "Generated by scripts/write_seedguard_schema_demo.py for path/format reference only.\n"
)


def main():
    os.makedirs(OUT_DIR, exist_ok=True)
    with tempfile.TemporaryDirectory() as tmp:
        rows = []
        for t in (1, 2):
            for i in (1, 2):
                rt = 0.10 + 0.02 * (t - 1)  # identical across inference seeds
                header = (
                    f"{{'seed': {t}, 'training_seed': {t}, 'inference_seed': {i}, "
                    f"'dataset': 'redial_gen_quick', 'test': True, "
                    f"'output_dir': 'save/train_seed_{t}/', "
                    f"'prompt_encoder': 'save/train_seed_{t}/best/'}}\n"
                )
                report = (
                    f"{{'test/recall@1': 0.05, 'test/recall@10': {0.2 + 0.01*(t-1):.4f}, "
                    f"'test/recall@50': 0.4, 'test/recall_true@1': 0.04, "
                    f"'test/recall_true@10': {rt:.4f}, 'test/recall_true@50': 0.3, "
                    f"'test/auc': {0.55 + 0.01*(t-1):.4f}, "
                    f"'test/precision@10': {0.02 + 0.002*(t-1):.4f}, "
                    f"'test/ndcg@10': 0.1, 'test/mrr@10': 0.08, 'test/loss': 1.0, "
                    f"'test/training_seed': {t}, 'test/inference_seed': {i}, 'epoch': 0}}\n"
                )
                path = os.path.join(tmp, f"{t}_{i}.log")
                with open(path, "w", encoding="utf-8") as f:
                    f.write(header + report)
                rows.extend(collect_results.parse_log(path))

        collect_results.write_seedguard_outputs(
            rows, OUT,
            experiment_id="schema_demo_synthetic",
            model_config="ecr_rec_schema_demo",
            inference_variation_meaningful=False,
        )

    readme = OUT + "_README.txt"
    with open(readme, "w", encoding="utf-8") as f:
        f.write(NOTE)
        f.write("Companion files: seedguard_schema_demo_seedguard_*.csv / .md\n")
    print("Wrote", readme)


if __name__ == "__main__":
    main()
